using System.Globalization;using Microsoft.Data.Sqlite;using StockSyncAI.Api.Models;namespace StockSyncAI.Api.Database;
public sealed class InvoicePostingRepository(SqliteConnectionFactory factory):IInvoicePostingRepository
{
 private const string Columns="id,invoice_id,review_fingerprint,snapshot_json,state,attempt_count,safe_error,result_json,confirmed_utc,created_utc,updated_utc";
 public async Task<InvoicePostingRecord?> GetAsync(Guid invoiceId,string fingerprint,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE invoice_id=$invoice AND review_fingerprint=$fingerprint";q.Parameters.AddWithValue("$invoice",invoiceId.ToString("D"));q.Parameters.AddWithValue("$fingerprint",fingerprint);await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?Read(r):null;}
 public async Task<InvoicePostingRecord?> GetByIdAsync(Guid id,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE id=$id";Add(q,"$id",id.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?Read(r):null;}
 public async Task<IReadOnlyList<InvoicePostingRecord>> ListAsync(Guid invoiceId,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE invoice_id=$invoice ORDER BY updated_utc DESC";q.Parameters.AddWithValue("$invoice",invoiceId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);var list=new List<InvoicePostingRecord>();while(await r.ReadAsync(token))list.Add(Read(r));return list;}
 public async Task<InvoicePostingRecord> PrepareAsync(Guid invoiceId,string fingerprint,string snapshot,DateTimeOffset now,CancellationToken token=default){var e=await GetAsync(invoiceId,fingerprint,token);if(e?.State is PostingStates.Posted or PostingStates.Posting or PostingStates.OutcomeUnknown)return e;var id=e?.Id??Guid.NewGuid();await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);await Execute(c,tx,"""INSERT INTO invoice_postings(id,invoice_id,review_fingerprint,snapshot_json,state,attempt_count,safe_error,result_json,confirmed_utc,created_utc,updated_utc) VALUES($id,$invoice,$fingerprint,$snapshot,'Prepared',0,NULL,NULL,NULL,$now,$now) ON CONFLICT(invoice_id,review_fingerprint) DO UPDATE SET snapshot_json=$snapshot,state='Prepared',safe_error=NULL,result_json=NULL,confirmed_utc=NULL,updated_utc=$now WHERE invoice_postings.state IN ('Prepared','FailedSafeToRetry','Blocked');""",[("$id",id.ToString("D")),("$invoice",invoiceId.ToString("D")),("$fingerprint",fingerprint),("$snapshot",snapshot),("$now",now.ToString("O"))],token);await Event(c,tx,id,null,Guid.NewGuid().ToString("D"),PostingRecoveryEventTypes.Prepared,"System",PostingTransactionOutcomes.NotStarted,"Posting snapshot prepared; no POS attempt was started.",null,now,token);await tx.CommitAsync(token);return(await GetAsync(invoiceId,fingerprint,token))!;}
 public async Task<PostingAttemptRecord?> TryStartAsync(Guid id,DateTimeOffset now,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="UPDATE invoice_postings SET state='Posting',attempt_count=attempt_count+1,safe_error=NULL,updated_utc=$now WHERE id=$id AND state IN ('Prepared','FailedSafeToRetry')";Add(q,"$id",id.ToString("D"));Add(q,"$now",now.ToString("O"));if(await q.ExecuteNonQueryAsync(token)!=1){await tx.RollbackAsync(token);return null;}await using var n=c.CreateCommand();n.Transaction=tx;n.CommandText="SELECT attempt_count FROM invoice_postings WHERE id=$id";Add(n,"$id",id.ToString("D"));var number=Convert.ToInt32(await n.ExecuteScalarAsync(token),CultureInfo.InvariantCulture);var attemptId=Guid.NewGuid();var correlation=Guid.NewGuid().ToString("D");await Execute(c,tx,"INSERT INTO posting_attempts(id,posting_id,attempt_number,correlation_id,transaction_outcome,last_operation,started_utc) VALUES($attempt,$posting,$number,$correlation,'InProgress','PostingAttemptStarted',$now)",[("$attempt",attemptId.ToString("D")),("$posting",id.ToString("D")),("$number",number),("$correlation",correlation),("$now",now.ToString("O"))],token);await Event(c,tx,id,attemptId,$"attempt-start:{attemptId:D}",PostingRecoveryEventTypes.AttemptStarted,"System",PostingTransactionOutcomes.InProgress,"POS posting attempt started; final transaction outcome is not yet known.",null,now,token);await tx.CommitAsync(token);return new(attemptId,id,number,correlation,PostingTransactionOutcomes.InProgress,"PostingAttemptStarted",now,null,null);}
 public async Task SetOutcomeAsync(Guid id,string state,string? error,string? result,DateTimeOffset? confirmed,DateTimeOffset now,CancellationToken token=default){if(state is not(PostingStates.Posted or PostingStates.FailedSafeToRetry or PostingStates.OutcomeUnknown or PostingStates.Blocked))throw new ArgumentOutOfRangeException(nameof(state));var outcome=state switch{PostingStates.Posted=>PostingTransactionOutcomes.Committed,PostingStates.FailedSafeToRetry=>PostingTransactionOutcomes.RolledBack,_=>PostingTransactionOutcomes.Unknown};var operation=state switch{PostingStates.Posted=>"SqlCommitConfirmed",PostingStates.FailedSafeToRetry=>"SqlRollbackConfirmed",PostingStates.OutcomeUnknown=>"TransactionOutcomeUnknown",_=>"PostingBlocked"};var eventType=state switch{PostingStates.Posted=>PostingRecoveryEventTypes.CommitConfirmed,PostingStates.FailedSafeToRetry=>PostingRecoveryEventTypes.RollbackConfirmed,_=>PostingRecoveryEventTypes.OutcomeBecameUnknown};var message=state switch{PostingStates.Posted=>"SQL Server commit was confirmed and persisted locally.",PostingStates.FailedSafeToRetry=>"SQL Server rollback was confirmed; a new attempt may be considered after revalidation.",_=>error??"The SQL Server transaction outcome could not be established."};await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);var attempt=await LatestAttempt(c,tx,id,token)??throw new InvalidOperationException("Posting attempt evidence is missing.");var changed=await Execute(c,tx,"UPDATE invoice_postings SET state=$state,safe_error=$error,result_json=$result,confirmed_utc=$confirmed,updated_utc=$now WHERE id=$id AND state='Posting'",[("$id",id.ToString("D")),("$state",state),("$error",error),("$result",result),("$confirmed",confirmed?.ToString("O")),("$now",now.ToString("O"))],token);if(changed!=1){await tx.RollbackAsync(token);throw new InvalidOperationException("Posting state changed unexpectedly.");}await Execute(c,tx,"UPDATE posting_attempts SET transaction_outcome=$outcome,last_operation=$operation,completed_utc=$now,safe_error=$error WHERE id=$attempt AND transaction_outcome='InProgress'",[("$attempt",attempt.Id.ToString("D")),("$outcome",outcome),("$operation",operation),("$now",now.ToString("O")),("$error",error)],token);await Event(c,tx,id,attempt.Id,$"attempt-outcome:{attempt.Id:D}",eventType,"System",outcome,message,result is null?null:"{\"verifiedIdentifiersPersisted\":true}",now,token);await tx.CommitAsync(token);}
 public async Task<StartupRecoveryResult> RecoverInterruptedAsync(DateTimeOffset now,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);var ids=new List<Guid>();await using(var find=c.CreateCommand()){find.Transaction=tx;find.CommandText="SELECT id FROM invoice_postings WHERE state='Posting'";await using var rows=await find.ExecuteReaderAsync(token);while(await rows.ReadAsync(token))ids.Add(Guid.Parse(rows.GetString(0)));}const string error="The application stopped while posting was active. SQL Server may have committed; automatic retry is blocked pending reconciliation.";foreach(var id in ids){token.ThrowIfCancellationRequested();var attempt=await LatestAttempt(c,tx,id,token);if(attempt is null)throw new InvalidOperationException("Active posting attempt evidence is missing.");await Execute(c,tx,"UPDATE invoice_postings SET state='OutcomeUnknown',safe_error=$error,updated_utc=$now WHERE id=$id AND state='Posting'",[("$id",id.ToString("D")),("$error",error),("$now",now.ToString("O"))],token);await Execute(c,tx,"UPDATE posting_attempts SET transaction_outcome='Unknown',last_operation='ApplicationRestartedDuringPosting',completed_utc=$now,safe_error=$error WHERE id=$attempt AND transaction_outcome='InProgress'",[("$attempt",attempt.Id.ToString("D")),("$now",now.ToString("O")),("$error",error)],token);await Event(c,tx,id,attempt.Id,$"startup-interrupted:{attempt.Id:D}",PostingRecoveryEventTypes.StartupInterruptedAttempt,"System",PostingTransactionOutcomes.Unknown,error,null,now,token);}await tx.CommitAsync(token);return new(ids.Count,ids);}
 public async Task<IReadOnlyList<PostingAttemptRecord>> ListAttemptsAsync(Guid postingId,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="SELECT id,posting_id,attempt_number,correlation_id,transaction_outcome,last_operation,started_utc,completed_utc,safe_error FROM posting_attempts WHERE posting_id=$posting ORDER BY attempt_number DESC";Add(q,"$posting",postingId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);var values=new List<PostingAttemptRecord>();while(await r.ReadAsync(token))values.Add(ReadAttempt(r));return values;}
 public async Task<IReadOnlyList<PostingRecoveryEventRecord>> ListEventsAsync(Guid postingId,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="SELECT id,posting_id,attempt_id,event_type,source,technical_outcome,message,evidence_json,created_utc FROM posting_recovery_events WHERE posting_id=$posting ORDER BY id DESC";Add(q,"$posting",postingId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);var values=new List<PostingRecoveryEventRecord>();while(await r.ReadAsync(token))values.Add(ReadEvent(r));return values;}
 public async Task<IReadOnlyList<PostingReconciliationDecisionRecord>> ListDecisionsAsync(Guid postingId,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="SELECT id,posting_id,attempt_id,decision,evidence_note,created_utc FROM posting_reconciliation_decisions WHERE posting_id=$posting ORDER BY created_utc DESC";Add(q,"$posting",postingId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);var values=new List<PostingReconciliationDecisionRecord>();while(await r.ReadAsync(token))values.Add(ReadDecision(r));return values;}
 public async Task AppendRecoveryInspectionAsync(Guid postingId,Guid requestId,string message,DateTimeOffset now,CancellationToken token=default){await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);if(await GetPostingInTransaction(c,tx,postingId,token) is null)throw new InvalidOperationException("Posting record was not found.");var attempt=await LatestAttempt(c,tx,postingId,token);await Event(c,tx,postingId,attempt?.Id,$"recovery-inspection:{requestId:D}",PostingRecoveryEventTypes.RecoveryInspected,"System",attempt?.TransactionOutcome??PostingTransactionOutcomes.NotStarted,message,null,now,token);await tx.CommitAsync(token);}
 public async Task<PostingReconciliationDecisionRecord> RecordDecisionAsync(Guid postingId,Guid requestId,string decision,string evidenceNote,DateTimeOffset now,CancellationToken token=default){if(!PostingReconciliationDecisions.IsValid(decision))throw new ArgumentOutOfRangeException(nameof(decision));await using var c=await factory.OpenAsync(token);await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(token);var posting=await GetPostingInTransaction(c,tx,postingId,token)??throw new InvalidOperationException("Posting record was not found.");if(posting.State!=PostingStates.OutcomeUnknown)throw new InvalidOperationException("Manual reconciliation decisions are accepted only for an unresolved outcome.");await using(var existing=c.CreateCommand()){existing.Transaction=tx;existing.CommandText="SELECT id,posting_id,attempt_id,decision,evidence_note,created_utc FROM posting_reconciliation_decisions WHERE request_id=$request";Add(existing,"$request",requestId.ToString("D"));await using var rows=await existing.ExecuteReaderAsync(token);if(await rows.ReadAsync(token)){var value=ReadDecision(rows);await tx.CommitAsync(token);return value;}}var attempt=await LatestAttempt(c,tx,postingId,token);var id=Guid.NewGuid();await Execute(c,tx,"INSERT INTO posting_reconciliation_decisions(id,posting_id,attempt_id,request_id,decision,evidence_note,created_utc) VALUES($id,$posting,$attempt,$request,$decision,$note,$now)",[("$id",id.ToString("D")),("$posting",postingId.ToString("D")),("$attempt",attempt?.Id.ToString("D")),("$request",requestId.ToString("D")),("$decision",decision),("$note",evidenceNote),("$now",now.ToString("O"))],token);await Event(c,tx,postingId,attempt?.Id,$"operator-decision:{requestId:D}",PostingRecoveryEventTypes.OperatorDecisionRecorded,"Operator",attempt?.TransactionOutcome??PostingTransactionOutcomes.Unknown,"An operator assessment was recorded. It does not verify the SQL Server transaction outcome.","{\"operatorAssertion\":true}",now,token);await tx.CommitAsync(token);return new(id,postingId,attempt?.Id,decision,evidenceNote,now);}
 private static async Task<InvoicePostingRecord?> GetPostingInTransaction(SqliteConnection c,SqliteTransaction tx,Guid id,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=$"SELECT {Columns} FROM invoice_postings WHERE id=$id";Add(q,"$id",id.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?Read(r):null;}
 private static async Task<PostingAttemptRecord?> LatestAttempt(SqliteConnection c,SqliteTransaction tx,Guid postingId,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT id,posting_id,attempt_number,correlation_id,transaction_outcome,last_operation,started_utc,completed_utc,safe_error FROM posting_attempts WHERE posting_id=$posting ORDER BY attempt_number DESC LIMIT 1";Add(q,"$posting",postingId.ToString("D"));await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?ReadAttempt(r):null;}
 private static async Task<int> Execute(SqliteConnection c,SqliteTransaction tx,string sql,IEnumerable<(string Name,object? Value)> parameters,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=sql;foreach(var p in parameters)Add(q,p.Name,p.Value);return await q.ExecuteNonQueryAsync(token);}
 private static Task Event(SqliteConnection c,SqliteTransaction tx,Guid postingId,Guid? attemptId,string key,string type,string source,string outcome,string message,string? evidence,DateTimeOffset now,CancellationToken token)=>Execute(c,tx,"INSERT OR IGNORE INTO posting_recovery_events(posting_id,attempt_id,deduplication_key,event_type,source,technical_outcome,message,evidence_json,created_utc) VALUES($posting,$attempt,$key,$type,$source,$outcome,$message,$evidence,$now)",[("$posting",postingId.ToString("D")),("$attempt",attemptId?.ToString("D")),("$key",key),("$type",type),("$source",source),("$outcome",outcome),("$message",message),("$evidence",evidence),("$now",now.ToString("O"))],token);
 private static PostingAttemptRecord ReadAttempt(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.GetInt32(2),r.GetString(3),r.GetString(4),r.GetString(5),Date(r.GetString(6))!.Value,Date(r,7),Text(r,8));
 private static PostingRecoveryEventRecord ReadEvent(SqliteDataReader r)=>new(r.GetInt64(0),Guid.Parse(r.GetString(1)),r.IsDBNull(2)?null:Guid.Parse(r.GetString(2)),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),Text(r,7),Date(r.GetString(8))!.Value);
 private static PostingReconciliationDecisionRecord ReadDecision(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.IsDBNull(2)?null:Guid.Parse(r.GetString(2)),r.GetString(3),r.GetString(4),Date(r.GetString(5))!.Value);
 private static InvoicePostingRecord Read(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),Guid.Parse(r.GetString(1)),r.GetString(2),r.GetString(3),r.GetString(4),r.GetInt32(5),Text(r,6),Text(r,7),Date(r,8),Date(r.GetString(9))!.Value,Date(r.GetString(10))!.Value);private static string? Text(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static DateTimeOffset? Date(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:Date(r.GetString(i));private static DateTimeOffset? Date(string v)=>DateTimeOffset.Parse(v,CultureInfo.InvariantCulture);private static void Add(SqliteCommand q,string n,object? v)=>q.Parameters.AddWithValue(n,v??DBNull.Value);
}
